build-trades.mjs.text:
// Regenerates trades.mjs from the `*-bid-calculator` ventures next to this
// one. Run `node build-trades.mjs` after one is added; trades.test.mjs fails if
// trades.mjs is stale or a trade has no category.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";

const root = new URL("../", import.meta.url);

// Starting points for the inputs, by kind of work. Planning defaults to edit,
// not industry benchmarks: a shop's own payroll bills and last year's books
// replace every one of them.
export const CATEGORIES = {
  exterior: { label: "Exterior and site work", burdenPct: 30, overheadPct: 15, marginPct: 25, contingencyPct: 8, wastePct: 10, laborHint: "16 @ 28 crew lead\n16 @ 22 helper" },
  interior: { label: "Interior and finish work", burdenPct: 28, overheadPct: 14, marginPct: 25, contingencyPct: 6, wastePct: 10, laborHint: "12 @ 30 installer\n12 @ 20 helper" },
  systems: { label: "Systems and installs (HVAC, electrical, plumbing, water, solar)", burdenPct: 32, overheadPct: 18, marginPct: 30, contingencyPct: 7, wastePct: 5, laborHint: "10 @ 38 licensed tech\n10 @ 22 helper" },
  outdoor: { label: "Lawn, tree, snow and seasonal work", burdenPct: 22, overheadPct: 12, marginPct: 30, contingencyPct: 5, wastePct: 5, laborHint: "6 @ 20 crew\n6 @ 18 crew" },
  service: { label: "Cleaning, hauling and remediation", burdenPct: 25, overheadPct: 12, marginPct: 30, contingencyPct: 8, wastePct: 0, laborHint: "8 @ 20 crew\n8 @ 18 crew" },
  specialist: { label: "Specialist and other", burdenPct: 25, overheadPct: 15, marginPct: 30, contingencyPct: 6, wastePct: 5, laborHint: "8 @ 30 lead\n8 @ 20 helper" },
};

const BY_CATEGORY = {
  exterior: "asphalt-driveway-pave asphalt-sealcoat automatic-driveway-gate chimney-sweep concrete concrete-lifting deck deck-staining exterior-painting fence flat-roof garage-door gravel-driveway gutter-guard gutter-install metal-roof paver-patio pergola pole-barn retaining-wall roofing screened-porch shed-install siding soffit-fascia stucco-repair sunroom tuckpointing wheelchair-ramp entry-door patio-door window-replacement skylight-install foundation-repair french-drain parking-lot-striping artificial-turf",
  interior: "attic-insulation basement-finishing cabinet-refinishing carpet-install countertop crown-molding drywall egress-window epoxy-garage-floor flooring hardwood-refinishing home-staging interior-door kitchen-tile-backsplash painting plantation-shutter popcorn-ceiling spray-foam walk-in-shower walk-in-tub window-tinting stair-lift home-elevator",
  systems: "boiler-replacement dryer-vent electrical-panel-upgrade ev-charger furnace hot-tub landscape-lighting irrigation-install mini-split pool-plaster radon-mitigation sauna-cold-plunge-install security-camera septic-pumping sewer-hydrojet sewer-line-replace solar-pv standby-generator sump-pump toilet-replacement vinyl-liner water-heater water-softener water-well-drilling well-pump fireplace-insert basement-waterproofing crawl-space-encapsulation",
  outdoor: "forestry-mulching holiday-light hydroseeding-job ice-dam-removal irrigation-winterization lawn-aeration-overseeding lawn-care pressure-washing snow-removal sod-install tree-service window-cleaning gutter-cleaning",
  service: "asbestos-abatement biohazard-cleanup carpet-cleaning duct-cleaning hood-cleaning hoarding-cleanout janitorial junk-removal mobile-detailing moving mold-remediation pest-control wildlife-exclusion pet-grooming auto-glass vehicle-wrap",
  specialist: "land-survey liquidation-pallet locksmith storage-auction-max",
};
const CATEGORY_OF = Object.fromEntries(Object.entries(BY_CATEGORY).flatMap(([c, s]) => s.split(/\s+/).map((slug) => [slug, c])));

export function listTrades() {
  return readdirSync(root, { withFileTypes: true })
    .filter((d) => d.isDirectory() && d.name.endsWith("-bid-calculator"))
    .map((d) => {
      const slug = d.name.replace(/-bid-calculator$/, "");
      const trade = slug.split("-").map((w) => w[0].toUpperCase() + w.slice(1)).join(" ");
      return { slug, trade, category: CATEGORY_OF[slug] ?? null, calculator: d.name };
    })
    .sort((a, b) => a.trade.localeCompare(b.trade));
}

export function renderModule(trades) {
  return `// Generated by build-trades.mjs. Do not edit by hand.\nexport const CATEGORIES = ${JSON.stringify(CATEGORIES, null, 2)};\nexport const TRADES = ${JSON.stringify(trades, null, 1).replace(/\n\s+/g, " ").replace(/\[ /, "[\n ").replace(/ \]$/, "\n]")};\n`.replace(/\}, \{/g, "},\n {");
}

if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href) {
  const trades = listTrades();
  const missing = trades.filter((t) => !t.category).map((t) => t.slug);
  if (missing.length) { console.error("No category for:", missing.join(", ")); process.exit(1); }
  writeFileSync(new URL("./trades.mjs", import.meta.url), renderModule(trades));
  console.log(`wrote trades.mjs (${trades.length} trades)`);
}

calc.mjs.text:
// Pure bid arithmetic shared by every trade. No network, no state. The one
// idea: price = full cost / (1 - margin). A "25% markup" on cost is a 20%
// margin on price, and a contractor who adds 25% when they meant a 25% margin
// is short on every job. Trades differ in their inputs, not in this maths.

export const round2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;

function pct(value, name, { max = 95 } = {}) {
  const n = Number(value ?? 0);
  if (!Number.isFinite(n) || n < 0) throw new Error(`${name} must be zero or more`);
  if (n > max) throw new Error(`${name} must be at most ${max}`);
  return n;
}
function amount(value, name) {
  const n = Number(value ?? 0);
  if (!Number.isFinite(n) || n < 0) throw new Error(`${name} must be zero or more`);
  return n;
}

// "16 @ 28 framing crew" -> { hours: 16, rate: 28, label: "framing crew" }
export function parseLabor(text) {
  const lines = [];
  for (const raw of String(text || "").split(/\r?\n/)) {
    const line = raw.trim();
    if (!line) continue;
    const m = line.match(/^(\d+(?:\.\d+)?)\s*(?:h|hrs?|hours?)?\s*[@x×]\s*\$?(\d+(?:\.\d+)?)\s*(?:\/\s*h(?:r|our)?)?\s*(.*)$/i);
    if (!m) throw new Error(`Labor line "${line}" should look like "16 @ 28 crew" (hours @ hourly wage)`);
    lines.push({ hours: Number(m[1]), rate: Number(m[2]), label: m[3].trim() });
  }
  return lines;
}

// "420 lumber" or "$85.50 hinges" -> { cost, label }
export function parseCosts(text, what = "Cost") {
  const lines = [];
  for (const raw of String(text || "").split(/\r?\n/)) {
    const line = raw.trim();
    if (!line) continue;
    const m = line.match(/^\$?(\d[\d,]*(?:\.\d+)?)\s*(.*)$/);
    if (!m) throw new Error(`${what} line "${line}" should start with a dollar amount, e.g. "420 lumber"`);
    lines.push({ cost: Number(m[1].replace(/,/g, "")), label: m[2].trim() });
  }
  return lines;
}

/**
 * Price a job.
 * @param {object} i
 * @param {{hours:number,rate:number}[]} i.labor  hourly wage lines (before burden)
 * @param {number} i.burdenPct       payroll taxes, workers' comp, benefits as % of wages
 * @param {{cost:number}[]} i.materials
 * @param {number} i.wastePct        extra material bought beyond what the job uses
 * @param {number} i.subs            subcontractor cost
 * @param {number} i.equipment       rentals, fuel, dump fees, permits and other direct cost
 * @param {number} i.travelMiles
 * @param {number} i.mileRate        cost per mile
 * @param {number} i.contingencyPct  % of direct cost held for surprises
 * @param {number} i.overheadPct     % of direct cost that pays for the business itself
 * @param {number} i.marginPct       target profit as % of the price (not of cost)
 * @param {number} [i.rivalPrice]    a competing bid, to see the margin it leaves
 * @param {number} [i.depositPct]
 */
export function priceJob(i) {
  const labor = (i.labor || []).map((l) => ({ hours: amount(l.hours, "Labor hours"), rate: amount(l.rate, "Hourly wage") }));
  const burdenPct = pct(i.burdenPct, "Payroll burden", { max: 200 });
  const wastePct = pct(i.wastePct, "Material waste", { max: 100 });
  const contingencyPct = pct(i.contingencyPct, "Contingency", { max: 100 });
  const overheadPct = pct(i.overheadPct, "Overhead", { max: 200 });
  const marginPct = pct(i.marginPct, "Target margin", { max: 90 });
  const depositPct = pct(i.depositPct ?? 0, "Deposit", { max: 100 });

  const hours = labor.reduce((s, l) => s + l.hours, 0);
  const wages = labor.reduce((s, l) => s + l.hours * l.rate, 0);
  const laborCost = wages * (1 + burdenPct / 100);
  const materialsUsed = (i.materials || []).reduce((s, m) => s + amount(m.cost, "Material cost"), 0);
  const materialCost = materialsUsed * (1 + wastePct / 100);
  const subs = amount(i.subs, "Subcontractors");
  const equipment = amount(i.equipment, "Equipment and fees");
  const travel = amount(i.travelMiles, "Travel miles") * amount(i.mileRate, "Cost per mile");

  const direct = laborCost + materialCost + subs + equipment + travel;
  const contingency = direct * (contingencyPct / 100);
  const overhead = direct * (overheadPct / 100);
  const fullCost = direct + contingency + overhead;
  const price = fullCost / (1 - marginPct / 100);
  const profit = price - fullCost;

  // The common mistake: typing the margin as a markup.
  const naivePrice = fullCost * (1 + marginPct / 100);
  const naiveMargin = naivePrice > 0 ? ((naivePrice - fullCost) / naivePrice) * 100 : 0;

  // Labor is the line that overruns. How far can it run over before the
  // contingency and then the profit are spent?
  const overrunBeforeProfitLoss = laborCost > 0 ? ((contingency + profit) / laborCost) * 100 : null;
  const overrunBeforeContingencyGone = laborCost > 0 ? (contingency / laborCost) * 100 : null;

  const out = {
    hours: round2(hours), wages: round2(wages), laborCost: round2(laborCost), materialCost: round2(materialCost),
    subs: round2(subs), equipment: round2(equipment), travel: round2(travel), direct: round2(direct),
    contingency: round2(contingency), overhead: round2(overhead), fullCost: round2(fullCost),
    price: round2(price), profit: round2(profit), marginPct: round2(marginPct),
    markupPct: round2((marginPct / (100 - marginPct)) * 100),
    // Below this you lose money on the job after overhead; below `cashFloor` you
    // do not even cover what you spend out of pocket.
    walkAway: round2(fullCost), cashFloor: round2(direct),
    profitPerLaborHour: hours > 0 ? round2(profit / hours) : null,
    revenuePerLaborHour: hours > 0 ? round2(price / hours) : null,
    naive: { price: round2(naivePrice), actualMarginPct: round2(naiveMargin), shortBy: round2(price - naivePrice) },
    overrunBeforeProfitLossPct: overrunBeforeProfitLoss === null ? null : round2(overrunBeforeProfitLoss),
    overrunBeforeContingencyGonePct: overrunBeforeContingencyGone === null ? null : round2(overrunBeforeContingencyGone),
    deposit: round2(price * (depositPct / 100)),
    depositCoversMaterialsPct: price > 0 ? round2(((materialCost + subs) / price) * 100) : 0,
  };

  const rival = i.rivalPrice === undefined || i.rivalPrice === "" || i.rivalPrice === null ? null : amount(i.rivalPrice, "Rival price");
  if (rival !== null && rival > 0) {
    const profitAtRival = rival - fullCost;
    out.rival = {
      price: round2(rival), profit: round2(profitAtRival),
      marginPct: round2((profitAtRival / rival) * 100),
      gapPct: round2(((price - rival) / rival) * 100),
      verdict: rival < direct ? "below-cash" : rival < fullCost ? "below-walk-away" : rival < price ? "thin" : "above-target",
    };
  }
  return out;
}

// Overhead as a % of direct cost, from last year's numbers.
export function overheadPctFrom(annualOverhead, annualDirectCost) {
  const o = amount(annualOverhead, "Annual overhead");
  const d = amount(annualDirectCost, "Annual direct cost");
  if (d <= 0) throw new Error("Annual direct cost must be above zero");
  return round2((o / d) * 100);
}

// Margin <-> markup, the conversion every quote gets wrong at least once.
export const marginToMarkup = (m) => round2((m / (100 - m)) * 100);
export const markupToMargin = (k) => round2((k / (100 + k)) * 100);

// What each +/- change in price does to the job and to the win chance you
// might face. No win-rate model here: see bid-win-rate-optimizer for that.
export function priceLadder(result, steps = [-10, -5, 0, 5, 10]) {
  return steps.map((s) => {
    const p = result.price * (1 + s / 100);
    return { change: s, price: round2(p), profit: round2(p - result.fullCost), marginPct: p > 0 ? round2(((p - result.fullCost) / p) * 100) : 0 };
  });
}

closeout.mjs.text:
// Close out a finished job against its bid, and learn from the jobs you have
// closed. Pure arithmetic: the page keeps the history on the visitor's own
// device. The point is the number a bid cannot show: what the job really left.

import { round2 } from "./calc.mjs";

function amount(value, name) {
  const n = Number(value ?? 0);
  if (!Number.isFinite(n) || n < 0) throw new Error(`${name} must be zero or more`);
  return n;
}

/**
 * Compare what a job cost with what the bid assumed.
 * @param {object} bid     the result of priceJob() plus { burdenPct, overheadPct }
 * @param {object} actual  { hours, materials, subs, equipment, travel, revenue }
 *   hours are paid labor hours at the bid's blended wage; revenue defaults to the bid price.
 */
export function closeoutJob(bid, actual) {
  if (!bid || !(bid.hours > 0)) throw new Error("A closeout needs a bid with labor hours to compare against");
  const hours = amount(actual.hours, "Actual labor hours");
  const materials = amount(actual.materials, "Actual materials");
  const subs = amount(actual.subs, "Actual subcontractors");
  const equipment = amount(actual.equipment, "Actual equipment and fees");
  const travel = actual.travel === undefined || actual.travel === "" ? bid.travel : amount(actual.travel, "Actual travel");
  const revenue = actual.revenue === undefined || actual.revenue === "" ? bid.price : amount(actual.revenue, "Revenue collected");
  if (!(revenue > 0)) throw new Error("Revenue collected must be above zero");

  const wage = bid.wages / bid.hours;
  const labor = hours * wage * (1 + bid.burdenPct / 100);
  const direct = labor + materials + subs + equipment + travel;
  const overhead = direct * (bid.overheadPct / 100);
  const fullCost = direct + overhead;
  const profit = revenue - fullCost;
  const pctOver = (a, b) => (b > 0 ? round2((a / b - 1) * 100) : null);

  return {
    labor: round2(labor), direct: round2(direct), overhead: round2(overhead), fullCost: round2(fullCost),
    revenue: round2(revenue), profit: round2(profit), marginPct: round2((profit / revenue) * 100),
    targetMarginPct: bid.marginPct, marginGapPts: round2((profit / revenue) * 100 - bid.marginPct),
    profitVsBid: round2(profit - bid.profit),
    laborHoursOverPct: pctOver(hours, bid.hours),
    materialsOverPct: pctOver(materials, bid.materialCost),
    directOverPct: pctOver(direct, bid.direct),
    profitPerLaborHour: hours > 0 ? round2(profit / hours) : null,
    // The bid's cash-in-hand view: did the job at least cover what left your account?
    coveredCash: revenue >= direct,
  };
}

/**
 * What a run of closed jobs says about your estimating.
 * Weighted by dollars, so one small job does not move it.
 * @param {object[]} jobs each { bidDirect, bidContingencyPct, bidLaborHours, actualHours, marginPct, targetMarginPct, profit, revenue }
 */
export function trackRecord(jobs, { minJobs = 3 } = {}) {
  const list = (jobs || []).filter((j) => j && j.bidDirect > 0 && j.revenue > 0);
  const n = list.length;
  if (n === 0) return { jobs: 0, ready: false };
  const sum = (f) => list.reduce((s, j) => s + f(j), 0);
  const bidDirect = sum((j) => j.bidDirect);
  const actualDirect = sum((j) => j.actualDirect);
  const bidHours = sum((j) => j.bidLaborHours);
  const actualHours = sum((j) => j.actualHours);
  const revenue = sum((j) => j.revenue);
  const profit = sum((j) => j.profit);
  const directOverPct = round2((actualDirect / bidDirect - 1) * 100);
  const laborOverPct = bidHours > 0 ? round2((actualHours / bidHours - 1) * 100) : null;
  const realizedMarginPct = round2((profit / revenue) * 100);
  const targetMarginPct = round2(sum((j) => j.targetMarginPct * j.revenue) / revenue);
  const underTarget = list.filter((j) => j.marginPct < j.targetMarginPct).length;
  const losers = list.filter((j) => j.profit < 0).length;
  // Contingency that would have covered the typical overrun, rounded up to a half point.
  const suggestedContingencyPct = directOverPct > 0 ? Math.ceil(directOverPct * 2) / 2 : 0;
  const currentContingencyPct = round2(sum((j) => j.bidContingencyPct * j.bidDirect) / bidDirect);
  return {
    jobs: n, ready: n >= minJobs, directOverPct, laborOverPct, realizedMarginPct, targetMarginPct,
    marginGapPts: round2(realizedMarginPct - targetMarginPct), underTarget, losers,
    currentContingencyPct, suggestedContingencyPct,
    contingencyShortfallPts: round2(Math.max(0, suggestedContingencyPct - currentContingencyPct)),
  };
}

link-calculators.mjs.text:
// Adds one line to every `*-bid-calculator` page pointing at the shared engine
// with that trade preselected (`../bid-price-engine/#trade=<slug>`), so the
// 120+ specialist pages pass visitors and link equity to the common spine.
// Idempotent: run `node link-calculators.mjs` after build-trades.mjs; the
// marker comment makes a second run replace the line rather than add another.
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { TRADES } from "./trades.mjs";

const MARK = "<!-- bid-price-engine-link -->";

export function engineLine(t) {
  return `  ${MARK}<p style="max-width:1060px;margin:0 auto;padding:0 18px 12px;font-size:.85rem;color:#5c5147">Want the margin, walk-away price and overrun headroom as well, or pricing a different trade? <a href="../bid-price-engine/#trade=${t.slug}">Price this job in the Bid Price Engine</a>, one calculator for ${TRADES.length} trades.</p>\n`;
}

export function linkAll(root = new URL("../", import.meta.url)) {
  let changed = 0;
  for (const t of TRADES) {
    const file = new URL(`${t.calculator}/index.html`, root);
    if (!existsSync(file)) continue;
    const html = readFileSync(file, "utf8");
    const line = engineLine(t);
    const old = new RegExp(`^ *${MARK}.*\\n`, "m");
    let next;
    if (old.test(html)) next = html.replace(old, () => line);
    else if (html.includes("<footer>")) next = html.replace("<footer>", () => line + "  <footer>");
    else continue;
    if (next === html) continue;
    writeFileSync(file, next);
    changed++;
  }
  return changed;
}

if (import.meta.url === `file://${process.argv[1]}`) console.log(`linked ${linkAll()} calculators`);

mobile/sync-web.mjs.text:
// Copies the web app (one directory up) into www/ for Capacitor. No bundler.
import { cpSync, rmSync, mkdirSync, readdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { join } from "node:path";

export const KEEP = /\.(html|mjs|webmanifest|png|js)$/;
const src = fileURLToPath(new URL("..", import.meta.url));
const out = fileURLToPath(new URL("./www", import.meta.url));

export function webFiles(dir = src) {
  return readdirSync(dir, { withFileTypes: true })
    .filter((e) => (e.isFile() && KEEP.test(e.name) && !/\.test\.mjs$/.test(e.name) && !/^build-|^link-/.test(e.name))
      || (e.isDirectory() && e.name === "icons"))
    .map((e) => e.name);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  rmSync(out, { recursive: true, force: true });
  mkdirSync(out, { recursive: true });
  for (const f of webFiles()) cpSync(join(src, f), join(out, f), { recursive: true });
  console.log(`copied ${webFiles().length} entries to www/`);
}

sw.js.text:
// Offline shell for the installed app. Caches this directory's own files only;
// there are no third-party requests and nothing is sent anywhere.
const CACHE = "bid-price-engine-v2";
const SHELL = [
  "./", "./index.html", "./calc.mjs", "./closeout.mjs", "./winrate.mjs", "./trades.mjs", "./usage.mjs",
  "./markup-vs-margin.html", "./manifest.webmanifest",
  "./icons/icon-192.png", "./icons/icon-512.png", "./icons/apple-touch-icon.png",
];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

// Network first so a fixed calculator reaches people at once; cache when offline.
self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET" || new URL(req.url).origin !== self.location.origin) return;
  event.respondWith(
    fetch(req)
      .then((res) => {
        const copy = res.clone();
        if (res.ok) caches.open(CACHE).then((c) => c.put(req, copy));
        return res;
      })
      .catch(() => caches.match(req).then((hit) => hit || caches.match("./index.html"))),
  );
});

usage.mjs.text:
const KEY = "bid-price-engine-usage";
// Separate from the counters on purpose: opting out *removes* the
// counters, so a flag stored inside them would be deleted by the very
// act it records.
const OPT_OUT = "bid-price-engine-usage-opt-out";

// The in-memory flag is only a same-page fast path. `globalThis` is a
// fresh realm on every page load, so without the stored key the switch
// silently stops working on the visitor's next visit -- and they do not
// look again, because they believe they already used it.
function usageOptedOut() {
  if (globalThis.__usageOptOut) return true;
  try {
    return typeof localStorage !== "undefined" && localStorage.getItem(OPT_OUT) === "1";
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

function usageBlocked() {
  if (usageOptedOut()) return true;
  try {
    if (navigator.doNotTrack === "1" || navigator.globalPrivacyControl) return true;
  } catch {
    /* navigator is optional in tests */
  }
  return false;
}

export function record(event) {
  if (typeof localStorage === "undefined" || usageBlocked()) return;
  let current;
  try {
    current = JSON.parse(localStorage.getItem(KEY) || "{}");
  } catch {
    current = {};
  }
  if (!current || typeof current !== "object" || Array.isArray(current)) current = {};
  current[event] = (current[event] || 0) + 1;
  try {
    localStorage.setItem(KEY, JSON.stringify(current));
  } catch {
    /* storage is optional */
  }
}

export function readUsage() {
  if (typeof localStorage === "undefined") return {};
  try {
    const parsed = JSON.parse(localStorage.getItem(KEY) || "{}");
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

export function setUsageOptOut(value) {
  const off = Boolean(value);
  globalThis.__usageOptOut = off;
  if (typeof localStorage === "undefined") return;
  if (off) {
    try { localStorage.removeItem(KEY); } catch { /* storage is optional */ }
    try { localStorage.setItem(OPT_OUT, "1"); } catch { /* storage is optional */ }
  } else {
    try { localStorage.removeItem(OPT_OUT); } catch { /* storage is optional */ }
  }
}

export { usageOptedOut };

winrate.mjs.text:
// Win-rate curve: which margin earns the most once you count the bids you lose.
// A margin chosen on the cost side alone ignores that a higher price wins less
// often. Given a log of past bids (the margin each carried, won or lost), this
// fits a logistic curve of win chance against margin and finds the margin that
// maximizes expected profit per bid. Pure arithmetic, no network: the page keeps
// the log on the visitor's own device.

import { round2 } from "./calc.mjs";

const MIN_BIDS = 8, MIN_EACH = 2;

const sigmoid = (t) => 1 / (1 + Math.exp(-t));

/** Margin of a bid as a percent of its price. */
export function bidMarginPct(price, fullCost) {
  const p = Number(price), c = Number(fullCost);
  if (!(p > 0) || !(c >= 0) || c >= p) return null;
  return ((p - c) / p) * 100;
}

// Ridge-penalised logistic fit of won ~ a + b*z, z = (x-mean)/sd, by Newton's method.
// The penalty on the slope keeps the fit finite when wins and losses separate cleanly.
function fit(xs, ys, mean, sd) {
  let a = 0, b = 0;
  const lambda = 0.5;
  for (let it = 0; it < 50; it++) {
    let ga = 0, gb = -lambda * b, haa = 0, hab = 0, hbb = lambda;
    for (let i = 0; i < xs.length; i++) {
      const z = (xs[i] - mean) / sd, p = sigmoid(a + b * z), w = p * (1 - p);
      ga += ys[i] - p; gb += (ys[i] - p) * z;
      haa += w; hab += w * z; hbb += w * z * z;
    }
    const det = haa * hbb - hab * hab;
    if (!(det > 1e-12)) break;
    const da = (hbb * ga - hab * gb) / det, db = (haa * gb - hab * ga) / det;
    a += da; b += db;
    if (Math.abs(da) + Math.abs(db) < 1e-9) break;
  }
  return { a, b };
}

function stats(xs) {
  const mean = xs.reduce((s, x) => s + x, 0) / xs.length;
  const sd = Math.sqrt(xs.reduce((s, x) => s + (x - mean) ** 2, 0) / xs.length);
  return { mean, sd };
}

// Expected profit per dollar of cost at margin m: P(win) * markup.
const markupOf = (m) => m / (100 - m);

function optimum(model, lo, hi) {
  let best = null;
  for (let m = lo; m <= hi + 1e-9; m += 0.25) {
    const pw = sigmoid(model.a + model.b * ((m - model.mean) / model.sd));
    const ev = pw * markupOf(m);
    if (!best || ev > best.ev) best = { margin: m, winChance: pw, ev };
  }
  return best;
}

// Small seeded generator so a bootstrap interval is the same on every load.
function mulberry32(seed) {
  let s = seed >>> 0;
  return () => { s = (s + 0x6d2b79f5) >>> 0; let t = s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}

/**
 * @param {{marginPct:number, won:boolean}[]} bids
 * @param {{bootstrap?:number}} [opts]
 */
export function winRateCurve(bids, { bootstrap = 200 } = {}) {
  const list = (bids || []).filter((b) => b && Number.isFinite(b.marginPct) && b.marginPct > 0 && b.marginPct < 90);
  const n = list.length, wins = list.filter((b) => b.won).length, losses = n - wins;
  const base = { bids: n, wins, losses };
  if (n < MIN_BIDS || wins < MIN_EACH || losses < MIN_EACH) {
    return { ...base, ready: false, need: Math.max(MIN_BIDS - n, 0), reason: n < MIN_BIDS ? "too-few" : "one-sided" };
  }
  const xs = list.map((b) => b.marginPct), ys = list.map((b) => (b.won ? 1 : 0));
  const { mean, sd } = stats(xs);
  if (sd < 1) return { ...base, ready: false, need: 0, reason: "no-spread" };
  const { a, b } = fit(xs, ys, mean, sd);
  const model = { a, b, mean, sd };
  if (!(b < 0)) return { ...base, ready: true, found: false, reason: "no-price-signal", winRate: round2((wins / n) * 100) };

  const lo = Math.max(1, Math.min(...xs) - 3), hi = Math.min(60, Math.max(...xs) + 3);
  const best = optimum(model, lo, hi);
  const avgMargin = mean;
  const atAvg = sigmoid(a + b * 0) * markupOf(avgMargin);

  const rand = mulberry32(2026);
  const opts = [];
  for (let r = 0; r < bootstrap; r++) {
    const bx = [], by = [];
    for (let i = 0; i < n; i++) { const k = Math.floor(rand() * n); bx.push(xs[k]); by.push(ys[k]); }
    const s1 = by.reduce((s, y) => s + y, 0);
    if (s1 < 1 || s1 > n - 1) continue;
    const st = stats(bx);
    if (st.sd < 0.5) continue;
    const f = fit(bx, by, st.mean, st.sd);
    if (!(f.b < 0)) continue;
    opts.push(optimum({ ...f, ...st }, lo, hi).margin);
  }
  opts.sort((p, q) => p - q);
  const pick = (q) => opts[Math.min(opts.length - 1, Math.floor(q * opts.length))];
  const interval = opts.length >= 20 ? { low: round2(pick(0.1)), high: round2(pick(0.9)) } : null;

  return {
    ...base, ready: true, found: true, winRate: round2((wins / n) * 100),
    slopePerPoint: round2(b / sd),
    bestMarginPct: round2(best.margin), winChanceAtBestPct: round2(best.winChance * 100),
    avgMarginPct: round2(avgMargin), winChanceAtAvgPct: round2(sigmoid(a) * 100),
    // Expected profit per $100 of cost, per bid you quote.
    evPer100AtBest: round2(best.ev * 100), evPer100AtAvg: round2(atAvg * 100),
    liftPct: atAvg > 0 ? round2((best.ev / atAvg - 1) * 100) : null,
    interval, confident: !!interval && interval.high - interval.low <= 8,
    winChanceAt: (m) => round2(sigmoid(a + b * ((m - mean) / sd)) * 100),
  };
}
